/* New independent 3D quality candidate, not an extension of capped native2D repairs: persist native field inventory before attempting measurements.
 * No initialize/step, synthetic field creation, or scientific/solver authorization.
 */
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.util.*;
import star.common.*;
import star.base.neo.ClientServerObject;
import star.base.report.ScalarReport;
public class ReadMeshRepair2Metrics extends StarMacro {
    // Root exact source/Spec/quality-readback certificate pending; empty pins hard refuse.
    private static final int SCIENTIFIC_MESH_REPAIR_INDEX=2,MAX_SCIENTIFIC_MESH_REPAIRS=2;
    private static final String FIXED_SPEC_SHA256="1e63f1b1b3ced209278c75f8532799f9d2c6cc33d47bf063ce361099e07ad407",FIXED_MESH_SHA256="f7ecd4f5460da94e7042d125c6b1b962692c30879f83445ac6146bb46b993b2b",FIXED_PIPELINE_SHA256="937c69c21c7fe4b5d7593bc79819bb4d24d50308ed7679a68ec49aacee57a27a";
    private static void fixedPin(File f,String h)throws Exception{if(!h.matches("[a-f0-9]{64}")||!f.isFile()||!hash(f).equals(h))throw new IllegalStateException("unreviewed immutable 3D quality input "+f.getName());}
    // Populate only after independent review of actual installed field-class inventory.
    private static final Map<String,String> EXPECTED_NATIVE_NEARWALL_CLASSES=Collections.emptyMap();
    private static String q(String x){StringBuilder b=new StringBuilder("\"");for(char c:x.toCharArray()){switch(c){case '"':b.append("\\\"");break;case '\\':b.append("\\\\");break;case '\n':b.append("\\n");break;case '\r':b.append("\\r");break;case '\t':b.append("\\t");break;default:if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}}return b.append('"').toString();}
    private static String hash(File f)throws Exception{MessageDigest m=MessageDigest.getInstance("SHA-256");m.update(Files.readAllBytes(f.toPath()));StringBuilder b=new StringBuilder();for(byte v:m.digest())b.append(String.format("%02x",v&255));return b.toString();}
    private static String stack(Throwable e){StringWriter w=new StringWriter();e.printStackTrace(new PrintWriter(w));return w.toString();}
    private static String fields(Collection<FieldFunction> fs){StringBuilder b=new StringBuilder("[");for(FieldFunction f:fs){if(b.length()>1)b.append(',');b.append("{\"function_name\":").append(q(f.getFunctionName())).append(",\"actual_class\":").append(q(f.getClass().getName())).append(",\"presentation_name\":").append(q(f.getPresentationName())).append('}');}return b.append(']').toString();}
    private static void lookupInventory(Simulation s,FvRepresentation v,File dir,String phase)throws Exception{
        List<FieldFunction> global=new ArrayList<>(s.getFieldFunctionManager().getObjects()),rep=new ArrayList<>();String error="null";
        try{rep.addAll(s.getFieldFunctionManager().getScalarFieldFunctions(v));}catch(Exception e){error=q(stack(e));}
        Files.writeString(new File(dir,"cellquality-lookup-"+phase+"-inventory.json").toPath(),"{\"status\":\"DIAGNOSTIC_ONLY\",\"phase\":"+q(phase)+",\"global_all_existing_types\":"+fields(global)+",\"representation_scalar_fields\":"+fields(rep)+",\"representation_error\":"+error+",\"quality_accepted\":false,\"science_accepted\":false,\"solve_authorized\":false}",StandardCharsets.UTF_8);
    }
    private static double minimum(Simulation s,FvRepresentation v,Region r,Class<?> type,List<ClientServerObject> tmp)throws Exception{
        String expectedName=type.equals(CellQualityFunction.class)?"CellQuality":type.equals(FaceValidityFunction.class)?"FaceValidity":type.equals(VolumeChangeFunction.class)?"VolumeChange":null;if(expectedName==null)throw new IllegalStateException("unknown native metric identity");
        FieldFunction selected=null;for(FieldFunction f:s.getFieldFunctionManager().getScalarFieldFunctions(v))if(f.getClass().equals(type)){if(selected!=null)throw new IllegalStateException("ambiguous exact native metric class "+type.getName());selected=f;}
        if(selected==null&&type.equals(CellQualityFunction.class)){
            File dir=s.getSessionDirFile();lookupInventory(s,v,dir,"before");
            try{
                // Official getFunction searches children and may synthesize a derived fallback.
                // Diagnostic lookup only; exact native class and representation binding remain required.
                FieldFunction candidate=s.getFieldFunctionManager().getFunction("CellQuality");
                boolean exact=candidate!=null&&candidate.getClass().equals(CellQualityFunction.class);
                boolean bound=candidate!=null&&candidate.isBoundToRepresentation(v);
                boolean nameMatches=candidate!=null&&"CellQuality".equals(candidate.getFunctionName());
                Files.writeString(new File(dir,"cellquality-lookup-result.json").toPath(),"{\"status\":\"DIAGNOSTIC_ONLY\",\"actual_class\":"+(candidate==null?"null":q(candidate.getClass().getName()))+",\"function_name\":"+(candidate==null?"null":q(candidate.getFunctionName()))+",\"exact_CellQualityFunction\":"+exact+",\"bound_to_representation\":"+bound+",\"accepted_for_measurement\":"+(exact&&bound&&nameMatches)+",\"quality_accepted\":false,\"science_accepted\":false,\"solve_authorized\":false}",StandardCharsets.UTF_8);
                if(!exact||!bound||!nameMatches||candidate instanceof UserFieldFunction)throw new IllegalStateException("CellQuality lookup returned unknown/derived/User/unbound field, not exact native CellQualityFunction");
                selected=candidate;
            }catch(Exception e){Files.writeString(new File(dir,"cellquality-lookup-failure.json").toPath(),"{\"status\":\"gate_failed\",\"phase\":\"diagnostic_CellQuality_lookup\",\"error\":"+q(e.toString())+",\"stack\":"+q(stack(e))+",\"quality_accepted\":false,\"science_accepted\":false,\"solve_authorized\":false}",StandardCharsets.UTF_8);throw e;}
            finally{lookupInventory(s,v,dir,"after");}
        }
        if(selected==null||!selected.getClass().equals(type)||selected instanceof UserFieldFunction||!expectedName.equals(selected.getFunctionName())||!selected.isBoundToRepresentation(v))throw new IllegalStateException("exact bound native metric unavailable: "+type.getName());
        ScalarReport report=s.getReportManager().create("star.base.report.MinReport");tmp.add(report);report.setRepresentation(v);report.setFieldFunction(selected);report.getParts().setObjects(r);double value=report.getReportMonitorValue();if(!Double.isFinite(value)||Math.abs(value)>=1e299)throw new IllegalStateException("invalid/empty native min "+type.getName());return value;
    }
    private static String nearwall(Simulation s,FvRepresentation v,Region r,Boundary wall,File dir,String id,List<ClientServerObject> tmp){
        boolean exists=s.getFieldFunctionManager().hasFunction(id);if(!exists)return "{\"id\":"+q(id)+",\"status\":\"NATIVE_EXISTING_FIELD_ABSENT\"}";
        FieldFunction selected=null;for(FieldFunction f:s.getFieldFunctionManager().getObjects())if(id.equals(f.getFunctionName())){if(selected!=null)return "{\"id\":"+q(id)+",\"status\":\"AMBIGUOUS_EXISTING_FIELD\"}";selected=f;}
        if(selected==null)return "{\"id\":"+q(id)+",\"status\":\"HASFUNCTION_WITHOUT_EXISTING_OBJECT_REJECTED\"}";
        String actual=selected.getClass().getName(),expected=EXPECTED_NATIVE_NEARWALL_CLASSES.get(id);
        if(selected instanceof UserFieldFunction||expected==null||!expected.equals(actual))return "{\"id\":"+q(id)+",\"actual_class\":"+q(actual)+",\"status\":\"CLASS_NOT_IN_INDEPENDENTLY_PINNED_NATIVE_REGISTRY\"}";
        if(id.equals("WallYplus")&&!s.getSolution().isInitialized())return "{\"id\":"+q(id)+",\"actual_class\":"+q(actual)+",\"status\":\"NOT_INITIALIZED_NO_MEANINGFUL_YPLUS\"}";
        try{XyzInternalTable t=s.getTableManager().createTable(XyzInternalTable.class);tmp.add(t);t.setRepresentation(v);t.getParts().setObjects(id.equals("WallDistance")?r:wall);t.setExtractVertexData(false);t.setFieldFunctions(Arrays.asList(selected));t.extract();if(t.getRowCount()<=0)throw new IllegalStateException("empty native table");File output=new File(dir,id.equals("WallDistance")?"native-volume-wall-distance.csv":"native-wall-face-yplus.csv");t.export(output.getAbsolutePath());return "{\"id\":"+q(id)+",\"actual_class\":"+q(actual)+",\"status\":\"NATIVE_EXISTING_EXACT_CLASS_EXPORT\",\"location\":"+q(id.equals("WallDistance")?"VOLUME_ALL_CELL_CENTRED_NOT_WALL_ADJACENCY_SUBSET":"WALL_FACE_CENTRED_NOT_VOLUME_CELL_VALUE")+",\"rows\":"+t.getRowCount()+",\"sha256\":"+q(hash(output))+"}";}catch(Exception e){return "{\"id\":"+q(id)+",\"phase\":\"nearwall_table_export\",\"status\":\"EXPORT_UNAVAILABLE\",\"error\":"+q(e.toString())+",\"stack\":"+q(stack(e))+"}";}
    }
    private static String geometryTable(Simulation s,FvRepresentation v,star.base.neo.NamedObject part,FieldFunction metric,File dir,String name,List<ClientServerObject> temporary)throws Exception{
        XyzInternalTable table=s.getTableManager().createTable(XyzInternalTable.class);temporary.add(table);table.setRepresentation(v);table.getParts().setObjects(part);table.setExtractVertexData(false);table.setFieldFunctions(Arrays.asList(metric));table.extract();int rows=table.getRowCount();if(rows<=0)throw new IllegalStateException("empty native XYZ metric table "+name);File csv=new File(dir,"native3d-geometry-"+name+".csv");table.export(csv.getAbsolutePath());if(!csv.isFile()||csv.length()==0)throw new IllegalStateException("missing/empty exported native geometry CSV "+name);
        return "{\"part\":"+q(name)+",\"file\":"+q(csv.getName())+",\"rows\":"+rows+",\"bytes\":"+csv.length()+",\"sha256\":"+q(hash(csv))+",\"field_class\":"+q(metric.getClass().getName())+",\"field_name\":"+q(metric.getFunctionName())+",\"extract_vertex_data\":false}";
    }
    private static void geometryExport(Simulation s,FvRepresentation v,Region r,File dir,List<ClientServerObject> temporary)throws Exception{
        FieldFunction metric=null;for(FieldFunction f:s.getFieldFunctionManager().getScalarFieldFunctions(v))if(f.getClass().equals(CellQualityFunction.class)&&"CellQuality".equals(f.getFunctionName())&&f.isBoundToRepresentation(v)){if(metric!=null)throw new IllegalStateException("ambiguous native geometry table metric");metric=f;}
        if(metric==null)metric=s.getFieldFunctionManager().getFunction("CellQuality");
        if(metric==null||!metric.getClass().equals(CellQualityFunction.class)||!"CellQuality".equals(metric.getFunctionName())||!metric.isBoundToRepresentation(v)||metric instanceof UserFieldFunction)throw new IllegalStateException("exact bound native CellQuality unavailable for XYZ export");
        StringBuilder entries=new StringBuilder("[");entries.append(geometryTable(s,v,r,metric,dir,"volume",temporary));
        for(String name:new String[]{"airfoil","farfield","symmetry_zmin","symmetry_zmax"}){Boundary boundary=r.getBoundaryManager().getBoundary(name);if(boundary==null)throw new IllegalStateException("missing geometry export boundary "+name);entries.append(',').append(geometryTable(s,v,boundary,metric,dir,name,temporary));}entries.append(']');
        Files.writeString(new File(dir,"native3d-geometry-export.json").toPath(),"{\"status\":\"ok\",\"verification_scope\":\"NATIVE_XYZ_TABLE_EXPORT_ONLY_SCHEMA_AND_SPAN_NOT_VERIFIED\",\"exports\":"+entries+",\"native_coordinate_units_verified\":false,\"actual_span_verified\":false,\"actual_layer_stations_verified\":false,\"wall_adjacency_mapping_verified\":false,\"actual_yplus_verified\":false,\"span_invariance_measured\":false,\"quality_accepted\":false,\"science_accepted\":false,\"solve_authorized\":false}",StandardCharsets.UTF_8);
    }
    @Override public void execute(){if(SCIENTIFIC_MESH_REPAIR_INDEX!=2||SCIENTIFIC_MESH_REPAIR_INDEX>MAX_SCIENTIFIC_MESH_REPAIRS)throw new IllegalStateException("scientific mesh repair limit");Simulation s=getActiveSimulation();File dir=s.getSessionDirFile(),out=new File(dir,"mesh_repair2_metrics.json");List<ClientServerObject> tmp=new ArrayList<>();String phase="field_inventory",inventory="null";long started=s.getSimulationIterator().getCurrentIteration();boolean initialized=s.getSolution().isInitialized(),finalRecordWritten=false;
        try{
            fixedPin(new File(dir,"case_spec.json"),FIXED_SPEC_SHA256);fixedPin(new File(dir,"naca0012-extruded3d.msh"),FIXED_MESH_SHA256);fixedPin(new File(dir,"pipeline-shape.json"),FIXED_PIPELINE_SHA256);
            File loadedSource=new File(dir,"naca0012-mesh-repair2-import.sim");if(!loadedSource.isFile())throw new IllegalStateException("previous-stage source artifact missing");String loadedSourceSha=hash(loadedSource);
            // Active source identity is also independently bound by immutable runner stage dependency.
            // Root must compare this hash with input_stage_SHA and prior citable successful output.
            if(initialized||started!=0)throw new IllegalStateException("uninitialized iteration-zero import source required");
            if(s.getContinuumManager().getObjects().size()!=1)throw new IllegalStateException("single imported empty metadata continuum required");Continuum imported=s.getContinuumManager().getObjects().iterator().next();if(!imported.getClass().getName().equals("star.common.PhysicsContinuum")||!(imported instanceof PhysicsContinuum))throw new IllegalStateException("exact imported metadata PhysicsContinuum required");PhysicsContinuum metadata=(PhysicsContinuum)imported;if(!metadata.getModelManager().getObjects().isEmpty())throw new IllegalStateException("active physics/source model forbidden before metadata-only enable");
            Files.writeString(new File(dir,"mesh-repair2-metadata-before.json").toPath(),"{\"status\":\"DIAGNOSTIC_ONLY\",\"actual_loaded_source_file_sha256\":"+q(loadedSourceSha)+",\"model_count\":0,\"active_physics_configured\":false,\"initialized\":false,\"iteration\":0}",StandardCharsets.UTF_8);
            Files.writeString(out.toPath(),"{\"status\":\"gate_failed\",\"phase\":\"started_not_completed\",\"quality_accepted\":false,\"science_accepted\":false,\"solve_authorized\":false}",StandardCharsets.UTF_8);
            FvRepresentation v=(FvRepresentation)s.getRepresentationManager().getObject("Volume Mesh");
            // Global inventory is an all-types superset: it includes scalars without filtering them away.
            List<FieldFunction> global=new ArrayList<>(s.getFieldFunctionManager().getObjects()),rep=new ArrayList<>();String repError="null";
            try{if(v!=null)rep.addAll(s.getFieldFunctionManager().getScalarFieldFunctions(v));}catch(Exception e){repError=q(stack(e));}
            inventory="{\"status\":\"ok\",\"global_scope\":\"ALL_EXISTING_TYPES_SUPERSET_INCLUDES_SCALARS\",\"global_fields\":"+fields(global)+",\"representation_scalar_fields\":"+fields(rep)+",\"representation_enumeration_error\":"+repError+"}";
            Files.writeString(new File(dir,"native-field-inventory.json").toPath(),inventory,StandardCharsets.UTF_8);
            StringBuilder text=new StringBuilder("scope\tfunction_name\tactual_class\tpresentation_name\n");for(FieldFunction f:global)text.append("global_all_types\t").append(f.getFunctionName()).append('\t').append(f.getClass().getName()).append('\t').append(f.getPresentationName()).append('\n');for(FieldFunction f:rep)text.append("representation_scalar\t").append(f.getFunctionName()).append('\t').append(f.getClass().getName()).append('\t').append(f.getPresentationName()).append('\n');Files.writeString(new File(dir,"native-field-inventory.txt").toPath(),text.toString(),StandardCharsets.UTF_8);
            phase="native3d_preconditions";File spec=new File(dir,"case_spec.json");if(!spec.isFile()||v==null||v.getCellCount()<=0||!v.is3D()||!v.isAtLeastOne3D()||v.isAtLeastOne2D()||s.getRegionManager().getRegions().size()!=1)throw new IllegalStateException("Spec and unique exclusively native3D mesh required");Region r=s.getRegionManager().getRegions().iterator().next();Boundary wall=r.getBoundaryManager().getBoundary("airfoil");if(!v.describesRegion(r)||!v.is3D(r)||wall==null||r.getBoundaryManager().getBoundary("farfield")==null||r.getBoundaryManager().getBoundaries().size()!=4)throw new IllegalStateException("native3D region/boundary identity mismatch");
            FvRegion nativeRegion=v.getFvRegionManager().getFvRegion(r);if(nativeRegion==null||!nativeRegion.is3D()||!s.getRepresentationManager().is3D(r))throw new IllegalStateException("native3D regional representation mismatch");
            for(String cap:new String[]{"symmetry_zmin","symmetry_zmax"}){Boundary b=r.getBoundaryManager().getBoundary(cap);if(b==null||!b.getBoundaryType().getClass().getName().equals("star.common.SymmetryBoundary")||!b.getDependentInterfaces().isEmpty())throw new IllegalStateException("3D cap must be exact symmetry without interface "+cap);}
            if(r.getBoundaryManager().getBoundary("farfield").getBoundaryType().getClass().getName().equals("star.common.WallBoundary"))throw new IllegalStateException("farfield unexpectedly solid wall");
            if(!wall.getBoundaryType().getClass().getName().equals("star.common.WallBoundary")||!wall.getDependentInterfaces().isEmpty()||!r.getBoundaryManager().getBoundary("farfield").getDependentInterfaces().isEmpty())throw new IllegalStateException("airfoil wall or boundary interface identity mismatch");
            if(r.getPhysicsContinuum()!=null&&!r.getPhysicsContinuum().equals(metadata))throw new IllegalStateException("region assigned to different active source continuum");
            phase="space_metadata_only_enable";metadata.enable(star.metrics.ThreeDimensionalModel.class);
            if(metadata.getModelManager().getObjects().size()!=1||metadata.getModelManager().getModel(star.metrics.ThreeDimensionalModel.class)==null)throw new IllegalStateException("only native ThreeDimensional space metadata model permitted");for(Model m:metadata.getModelManager().getObjects())if(!m.getClass().getName().equals("star.metrics.ThreeDimensionalModel"))throw new IllegalStateException("unexpected active physical model");
            Files.writeString(new File(dir,"mesh-repair2-metadata-after.json").toPath(),"{\"status\":\"DIAGNOSTIC_ONLY\",\"actual_loaded_source_file_sha256\":"+q(loadedSourceSha)+",\"models\":[\"star.metrics.ThreeDimensionalModel\"],\"space_metadata_enabled\":true,\"active_physics_configured\":false,\"science_accepted\":false,\"solve_authorized\":false}",StandardCharsets.UTF_8);
            lookupInventory(s,v,dir,"after-space-metadata");
            phase="nearwall_existing_field_diagnostic";String near="["+nearwall(s,v,r,wall,dir,"WallDistance",tmp)+","+nearwall(s,v,r,wall,dir,"WallYplus",tmp)+"]";Files.writeString(new File(dir,"native-nearwall-diagnostic.json").toPath(),"{\"status\":\"DIAGNOSTIC_ONLY\",\"fields\":"+near+",\"wall_adjacency_mapping_verified\":false,\"science_accepted\":false,\"solve_authorized\":false}",StandardCharsets.UTF_8);
            phase="native_metric_measurements";Class<?>[] types={CellQualityFunction.class,FaceValidityFunction.class,VolumeChangeFunction.class};String[] names={"CellQuality","FaceValidity","VolumeChange"};double[] values=new double[3];boolean complete=true;StringBuilder measurements=new StringBuilder("[");
            for(int i=0;i<3;i++){if(i>0)measurements.append(',');try{values[i]=minimum(s,v,r,types[i],tmp);measurements.append("{\"name\":").append(q(names[i])).append(",\"expected_native_class\":").append(q(types[i].getName())).append(",\"status\":\"MEASURED\",\"min\":").append(values[i]).append('}');}catch(Exception e){complete=false;measurements.append("{\"name\":").append(q(names[i])).append(",\"expected_native_class\":").append(q(types[i].getName())).append(",\"status\":\"UNAVAILABLE_NOT_MEASURED\",\"phase\":\"native_metric_measurements\",\"error\":").append(q(e.toString())).append(",\"stack\":").append(q(stack(e))).append('}');}}measurements.append(']');
            boolean passed=complete&&values[0]>=1e-5&&values[1]>=1&&values[2]>.01;
            Files.writeString(new File(dir,"native3d-metric-values-before-geometry-export.json").toPath(),"{\"status\":\"DIAGNOSTIC_ONLY\",\"metric_measurements\":"+measurements+",\"metric_measurements_complete\":"+complete+",\"actual_loaded_source_file_sha256\":"+q(loadedSourceSha)+",\"source_binding_scope\":\"POSTVERIFY_RUNNER_INPUT_STAGE_AND_PRIOR_CITABLE_OUTPUT_REQUIRED\",\"space_metadata_enabled\":true,\"active_physics_configured\":false,\"pilot_allowed\":false,\"metric_gates_passed\":"+passed+",\"quality_accepted\":false,\"science_accepted\":false,\"solve_authorized\":false}",StandardCharsets.UTF_8);
            if(complete){phase="native_geometry_xyz_table_export";try{geometryExport(s,v,r,dir,tmp);}catch(Exception exportFailure){Files.writeString(new File(dir,"native3d-geometry-export.json").toPath(),"{\"status\":\"gate_failed\",\"phase\":\"native_geometry_xyz_table_export\",\"error\":"+q(exportFailure.toString())+",\"stack\":"+q(stack(exportFailure))+",\"actual_span_verified\":false,\"quality_accepted\":false,\"science_accepted\":false,\"solve_authorized\":false}",StandardCharsets.UTF_8);throw exportFailure;}}

            if(!hash(loadedSource).equals(loadedSourceSha))throw new IllegalStateException("loaded source artifact bytes changed during readonly diagnosis");
            if(s.getSimulationIterator().getCurrentIteration()!=started||s.getSolution().isInitialized()!=initialized)throw new IllegalStateException("readonly solution state changed");
            String result="{\"status\":"+q(complete?"ok":"gate_failed")+",\"verification_scope\":\"MESH_REPAIR2_GEOMETRY_METRIC_DIAGNOSTIC\",\"phase\":\"native_metric_measurements\",\"failure_kind\":"+(complete?"null":"\"NATIVE_METRIC_UNAVAILABLE_NOT_A_QUALITY_FAILURE\"")+",\"spec_sha256\":"+q(hash(spec))+",\"cells\":"+v.getCellCount()+",\"metric_measurements\":"+measurements+",\"metric_measurements_complete\":"+complete+",\"actual_loaded_source_file_sha256\":"+q(loadedSourceSha)+",\"source_binding_scope\":\"POSTVERIFY_RUNNER_INPUT_STAGE_AND_PRIOR_CITABLE_OUTPUT_REQUIRED\",\"space_metadata_enabled\":true,\"active_physics_configured\":false,\"pilot_allowed\":false,\"metric_gates_passed\":"+passed+",\"cell_quality_bound\":0.00001,\"face_validity_bound\":1,\"volume_change_strict_bound\":0.01,\"start_iteration\":"+started+",\"end_iteration\":"+s.getSimulationIterator().getCurrentIteration()+",\"initialized_before\":"+initialized+",\"initialized_after\":"+s.getSolution().isInitialized()+",\"quality_accepted\":false,\"science_accepted\":false,\"solve_authorized\":false}";Files.writeString(out.toPath(),result,StandardCharsets.UTF_8);finalRecordWritten=true;if(!complete)throw new IllegalStateException("native metric unavailable; diagnostics preserved");s.println("MESH_REPAIR2_METRIC_DIAGNOSTIC_COMPLETE");
        }catch(Exception e){try{Files.writeString(new File(dir,"native-quality-failure.json").toPath(),"{\"status\":\"gate_failed\",\"phase\":"+q(phase)+",\"error\":"+q(e.toString())+",\"stack\":"+q(stack(e))+",\"inventory_preserved\":"+(!inventory.equals("null"))+",\"science_accepted\":false,\"solve_authorized\":false}",StandardCharsets.UTF_8);if(!finalRecordWritten)Files.writeString(out.toPath(),"{\"status\":\"gate_failed\",\"phase\":"+q(phase)+",\"error\":"+q(e.toString())+",\"stack\":"+q(stack(e))+",\"quality_accepted\":false,\"science_accepted\":false,\"solve_authorized\":false}",StandardCharsets.UTF_8);}catch(Exception writeFailure){e.addSuppressed(writeFailure);}throw new RuntimeException(e);}
        finally{Collections.reverse(tmp);for(ClientServerObject o:tmp)try{s.deleteObjects(Collections.singletonList(o));}catch(Exception cleanup){s.println("readonly diagnostic cleanup failed: "+cleanup);}}
    }
}
